export function variantsLabels(lang){return Object.fromEntries(variantKeys.map((key,i)=>[key,(variantWords[lang]||variantWords.EN)[i]]));}
export function validateVariantsLabels(){return Object.values(variantWords).length===8&&Object.values(variantWords).every(v=>v.length===variantKeys.length&&v.every(Boolean));}
